import { useContext } from 'react';

import { XYChartXScalesContext } from '../context/XYChartXScalesContext.js';

export const useXYChartXScales = () => {
  const context = useContext(XYChartXScalesContext);

  if (context === undefined) {
    throw new Error(
      'useXYChartXScales must be used within a XYChartXScalesContext',
    );
  }

  return context;
};
